package com.rezoxnemesis.videostudio;

import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.UUID;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE)
public class OpenPipelineRequestTemplateTest {
    private ProjectStore.Project source(){ProjectStore.Project p=new ProjectStore.Project();p.id="template_project";p.updatedAt=17;for(String id:new String[]{"source_a","source_b"}){ProjectStore.Asset a=new ProjectStore.Asset();a.id=id;a.mime="image/png";p.assets.add(a);}return p;}
    private JSONObject template()throws Exception {JSONObject timeline=Cinematic3DTimelineTest.timeline();timeline.getJSONArray("shots").getJSONObject(0).put("sourceAnchors",new JSONArray().put(new JSONObject().put("assetId","source_a").put("sha256","a".repeat(64))).put(new JSONObject().put("assetId","source_b").put("sha256","b".repeat(64))).put(new JSONObject().put("assetId","source_a").put("sha256","a".repeat(64))));return new JSONObject().put("projectId","template_project").put("sourceProjectUpdatedAt",17).put("backend","blender").put("controls",new JSONObject().put("timeline",timeline).put("renderFrames",0).put("conditioningFrames",new JSONArray())).put("assetIds",new JSONArray().put("source_b").put("source_a"));}
    @Test public void inertTemplatePreservesSelectedOrderAndLiteralRepeatedAnchors()throws Exception {JSONObject input=template(),accepted=OpenPipelineRequestTemplate.validate(input.toString(),source());assertEquals(OpenPipelineOperations.canonical(input),OpenPipelineOperations.canonical(accepted));assertEquals("source_b",accepted.getJSONArray("assetIds").getString(0));assertEquals(3,accepted.getJSONObject("controls").getJSONObject("timeline").getJSONArray("shots").getJSONObject(0).getJSONArray("sourceAnchors").length());assertFalse(accepted.has("requestId"));assertFalse(accepted.has("queued"));}
    @Test public void staleForeignExtraAndUnownedReferencesCannotLoad()throws Exception {JSONObject stale=template().put("sourceProjectUpdatedAt",18);assertThrows(IllegalStateException.class,()->OpenPipelineRequestTemplate.validate(stale.toString(),source()));JSONObject foreign=template().put("projectId","other_project");assertThrows(IllegalStateException.class,()->OpenPipelineRequestTemplate.validate(foreign.toString(),source()));JSONObject secret=template().put("bearer","do-not-configure-from-a-template");assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.validate(secret.toString(),source()));JSONObject missing=template().put("assetIds",new JSONArray().put("source_b"));assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.validate(missing.toString(),source()));JSONObject duplicate=template().put("assetIds",new JSONArray().put("source_b").put("source_a").put("source_a"));assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.validate(duplicate.toString(),source()));JSONObject running=template();running.getJSONObject("controls").put("renderFrames",1);assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.validate(running.toString(),source()));assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.validate("x".repeat(OpenPipelineArtifacts.MAX_JSON+1),source()));}
    @Test public void capturedSourceBytesMustMatchEveryAuthoredAnchor()throws Exception {JSONObject controls=OpenPipelineRequestTemplate.validate(template().toString(),source()).getJSONObject("controls");JSONArray sources=new JSONArray().put(new JSONObject().put("assetId","source_b").put("sha256","b".repeat(64))).put(new JSONObject().put("assetId","source_a").put("sha256","a".repeat(64)));OpenPipelineRequestTemplate.verifySourceBindings(controls,sources);sources.getJSONObject(1).put("sha256","c".repeat(64));assertThrows(IllegalStateException.class,()->OpenPipelineRequestTemplate.verifySourceBindings(controls,sources));}
    @Test public void fileHandoffReadsOnlyItsOwnedImmutableHashBoundNamespace()throws Exception {android.content.Context c=RuntimeEnvironment.getApplication();File root=new File(c.getFilesDir(),"open_pipeline_templates");root.mkdirs();String name=UUID.randomUUID()+".json";File file=new File(root,name);String raw=template().toString();byte[] bytes=raw.getBytes(StandardCharsets.UTF_8);Files.write(file.toPath(),bytes);String hash=OpenPipelineArtifacts.hash(bytes);assertEquals(raw,OpenPipelineRequestTemplate.readHandoff(c,null,name,hash));assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.readHandoff(c,raw,name,hash));assertThrows(IllegalArgumentException.class,()->OpenPipelineRequestTemplate.readHandoff(c,null,"../foreign.json",hash));Files.write(file.toPath(),"{}".getBytes(StandardCharsets.UTF_8));assertThrows(IllegalStateException.class,()->OpenPipelineRequestTemplate.readHandoff(c,null,name,hash));file.delete();}
    @Test public void largeAuthoredPoseControlsExportWithinTheRealRequestBudget()throws Exception {
        android.content.Context context=RuntimeEnvironment.getApplication();ProjectStore store=new ProjectStore(context);ProjectStore.Project source=store.create("Large authored rebuild");JSONObject timeline=Cinematic3DTimelineTest.timeline().put("motionProvider","authored_3d");JSONArray keys=new JSONArray();
        for(int i=0;i<128;i++){JSONObject actors=new JSONObject();for(String actor:new String[]{"black","white"}){JSONArray rotations=new JSONArray();for(int joint=0;joint<16;joint++)rotations.put(new JSONArray().put(Math.sqrt(.5)).put(Math.sqrt(.2)).put(Math.sqrt(.15)).put(Math.sqrt(.15)));actors.put(actor,new JSONObject().put("root",new JSONArray().put(.1234567890123456).put(1.0123456789012345).put(-.1234567890123456)).put("rotations",rotations));}keys.put(new JSONObject().put("phase",i/127d).put("actors",actors));}timeline.getJSONArray("shots").getJSONObject(0).put("poseKeyframes",keys);
        JSONObject controls=OpenPipelineOperations.validateControls("blender",new JSONObject().put("timeline",timeline).put("renderFrames",0).put("conditioningFrames",new JSONArray()));int bytes=controls.toString().getBytes(StandardCharsets.UTF_8).length;assertTrue("Fixture must exercise the removed 256 KiB ceiling",bytes>OpenPipelineArtifacts.MAX_JSON/2);assertTrue(bytes<OpenPipelineArtifacts.MAX_JSON);
        String id="large_"+UUID.randomUUID();JSONObject parameters=new JSONObject().put("projectId",source.id).put("sourceProjectUpdatedAt",source.updatedAt).put("requestId",id).put("backend","blender").put("controls",controls).put("assetIds",new JSONArray());JSONObject exported=OpenPipelineOperations.execute(context,store,"open_pipeline_export_request",parameters,null);assertEquals("exported",exported.getString("state"));JSONObject record=new OpenPipelineStore(context).get(id);assertEquals(128,record.getJSONObject("request").getJSONObject("controls").getJSONObject("timeline").getJSONArray("shots").getJSONObject(0).getJSONArray("poseKeyframes").length());assertEquals(source.updatedAt,store.get(source.id).updatedAt);
    }
    @Test public void largerLocalReceiptsCannotRelaxTheFinalRequestBudget()throws Exception {File root=Files.createTempDirectory("pipeline-budget-").toFile();String padding="x".repeat(OpenPipelineArtifacts.MAX_JSON);JSONObject local=new JSONObject().put("padding",padding);File record=new File(root,"record.json");OpenPipelineArtifacts.writeAtomic(record,local.toString().getBytes(StandardCharsets.UTF_8),OpenPipelineStore.MAX_RECORD_BYTES);assertEquals(padding.length(),OpenPipelineArtifacts.json(record,OpenPipelineStore.MAX_RECORD_BYTES).getString("padding").length());assertThrows(IllegalArgumentException.class,()->OpenPipelineArtifacts.json(record));JSONObject oversized=new JSONObject().put("schema",OpenPipelineArtifacts.REQUEST_SCHEMA).put("sources",new JSONArray()).put("padding",padding);File archive=new File(root,"too-large.vsjob");assertThrows(IllegalArgumentException.class,()->OpenPipelineArtifacts.packageRequest(root,oversized,archive));assertFalse(archive.exists());}
}
